"""Build a lightweight claim map for deep-review workflows."""

from __future__ import annotations

import argparse
import json
import re
from pathlib import Path

CLAIM_PATTERNS = (
    r"\bwe (?:show|demonstrate|find|propose|introduce|present)\b",
    r"\bour results?\b",
    r"\bthis paper\b",
    r"\bthe main contribution\b",
    r"\bwe conclude\b",
    r"\bwe argue\b",
)


def split_sentences(text: str) -> list[str]:
    """Split text into rough sentences without external dependencies."""
    parts = re.split(r"(?<=[.!?])\s+(?=[A-Z0-9\"'])", text.replace("\n", " "))
    return [part.strip() for part in parts if part.strip()]


def extract_claims(text: str, max_items: int = 5) -> list[str]:
    """Return likely claim-bearing sentences."""
    claims: list[str] = []
    for sentence in split_sentences(text):
        if any(re.search(pattern, sentence, re.IGNORECASE) for pattern in CLAIM_PATTERNS):
            claims.append(sentence)
        if len(claims) >= max_items:
            break
    return claims


def build_claim_map(
    content: str,
    section_index: list[dict],
    section_texts: dict[str, str] | None = None,
    max_items_per_section: int = 5,
) -> dict:
    """Build a minimal section-aware claim map from text and section index."""
    lines = content.splitlines()
    section_claims: dict[str, list[str]] = {}
    headline_claims: list[str] = []
    closure_targets: list[str] = []

    for section in section_index:
        if section_texts and section["section_key"] in section_texts:
            chunk = section_texts[section["section_key"]]
        else:
            start = int(section.get("start_line", 1))
            end = int(section.get("end_line", len(lines)))
            if section.get("line_base", 1) == 0:
                chunk = "\n".join(lines[start : end + 1])
            else:
                chunk = "\n".join(lines[max(0, start - 1) : end])

        claims = extract_claims(chunk, max_items=max_items_per_section)
        if claims:
            section_claims[section["section_key"]] = claims

        if section["section_key"] in {"abstract", "introduction"}:
            headline_claims.extend(claims[:max_items_per_section])
        if section["section_key"] in {"conclusion", "discussion"}:
            closure_targets.extend(claims[:max_items_per_section])

    return {
        "headline_claims": headline_claims[: max_items_per_section * 2],
        "closure_targets": closure_targets[: max_items_per_section * 2],
        "section_claims": section_claims,
    }


def main() -> int:
    parser = argparse.ArgumentParser(description="Build a claim map from a deep-review workspace")
    parser.add_argument("full_text", help="Path to full_text.md")
    parser.add_argument("section_index", help="Path to section_index.json")
    parser.add_argument("--output", "-o", help="Optional output path")
    args = parser.parse_args()

    full_text = Path(args.full_text).read_text(encoding="utf-8")
    section_index = json.loads(Path(args.section_index).read_text(encoding="utf-8"))
    claim_map = build_claim_map(full_text, section_index)
    payload = json.dumps(claim_map, indent=2, ensure_ascii=False)

    if args.output:
        Path(args.output).write_text(payload, encoding="utf-8")
    else:
        print(payload)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Consolidate deep-review lane findings into a final issue bundle."""

from __future__ import annotations

import argparse
import json
import re
from pathlib import Path

SEVERITY_ORDER = {"major": 0, "moderate": 1, "minor": 2}
CONFIDENCE_ORDER = {"high": 0, "medium": 1, "low": 2}
VALID_TYPES = {"methodology", "claim_accuracy", "presentation", "missing_information"}
VALID_SOURCE_KINDS = {"llm", "script"}


def slugify(value: str) -> str:
    """Create a normalized key for root cause comparisons."""
    return re.sub(r"[^a-z0-9]+", "-", value.lower()).strip("-") or "issue"


def sanitize_issue(issue: dict) -> dict:
    """Fill defaults and normalize the expected issue schema."""
    title = issue.get("title", "Untitled issue").strip()
    quote = issue.get("quote", "").strip()
    explanation = issue.get("explanation", "").strip()
    severity = str(issue.get("severity", "moderate")).lower()
    comment_type = issue.get("comment_type", "missing_information")
    source_kind = str(issue.get("source_kind", "llm")).lower()
    confidence = str(issue.get("confidence", "medium")).lower()

    if severity not in SEVERITY_ORDER:
        severity = "moderate"
    if comment_type not in VALID_TYPES:
        comment_type = "missing_information"
    if source_kind not in VALID_SOURCE_KINDS:
        source_kind = "llm"
    if confidence not in CONFIDENCE_ORDER:
        confidence = "medium"

    related = [item for item in issue.get("related_sections", []) if item]
    section = issue.get("source_section", "").strip()
    if section and section not in related:
        related = [section, *related]

    return {
        "title": title,
        "quote": quote,
        "explanation": explanation,
        "comment_type": comment_type,
        "severity": severity,
        "confidence": confidence,
        "source_kind": source_kind,
        "source_section": section,
        "related_sections": related,
        "root_cause_key": issue.get("root_cause_key") or slugify(title),
        "review_lane": issue.get("review_lane", "").strip(),
        "gate_blocker": bool(issue.get("gate_blocker", severity == "major")),
        "quote_verified": issue.get("quote_verified"),
    }


def load_comment_files(comments_dir: Path) -> list[dict]:
    """Load every JSON file from the comments directory."""
    findings: list[dict] = []
    for path in sorted(comments_dir.glob("*.json")):
        payload = json.loads(path.read_text(encoding="utf-8"))
        items = payload if isinstance(payload, list) else payload.get("issues", [])
        for raw_issue in items:
            issue = sanitize_issue(raw_issue)
            issue["source_file"] = path.name
            findings.append(issue)
    return findings


def consolidate_findings(issues: list[dict]) -> list[dict]:
    """Deduplicate exact overlaps while keeping distinct consequences separate."""
    consolidated: list[dict] = []
    seen: dict[tuple[str, str, str, str], int] = {}

    for issue in issues:
        key = (
            issue["root_cause_key"],
            issue["comment_type"],
            issue["source_section"],
            slugify(issue["quote"][:160] or issue["title"]),
        )
        if key not in seen:
            seen[key] = len(consolidated)
            consolidated.append(issue)
            continue

        current = consolidated[seen[key]]
        if SEVERITY_ORDER[issue["severity"]] < SEVERITY_ORDER[current["severity"]]:
            current["severity"] = issue["severity"]
        if CONFIDENCE_ORDER[issue["confidence"]] < CONFIDENCE_ORDER[current["confidence"]]:
            current["confidence"] = issue["confidence"]
        if len(issue["explanation"]) > len(current["explanation"]):
            current["explanation"] = issue["explanation"]
        for section in issue["related_sections"]:
            if section and section not in current["related_sections"]:
                current["related_sections"].append(section)
        if issue["review_lane"] and issue["review_lane"] not in current["review_lane"]:
            current["review_lane"] = ", ".join(
                [part for part in [current["review_lane"], issue["review_lane"]] if part]
            )
        current["gate_blocker"] = current["gate_blocker"] or issue["gate_blocker"]

    return sorted(
        consolidated,
        key=lambda item: (
            SEVERITY_ORDER[item["severity"]],
            item["source_section"],
            item["title"].lower(),
        ),
    )


def main() -> int:
    parser = argparse.ArgumentParser(description="Consolidate deep-review finding JSON files")
    parser.add_argument("review_dir", help="Path to a prepared review workspace")
    args = parser.parse_args()

    review_dir = Path(args.review_dir).resolve()
    comments_dir = review_dir / "comments"
    findings = load_comment_files(comments_dir)
    consolidated = consolidate_findings(findings)

    (review_dir / "all_comments.json").write_text(
        json.dumps(findings, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )
    (review_dir / "final_issues.json").write_text(
        json.dumps(consolidated, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )

    for issue in consolidated:
        print(f"- {issue['severity'].upper()}: {issue['title']}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Diff two deep-review issue bundles for re-audit style comparisons."""

from __future__ import annotations

import argparse
import json
from pathlib import Path


def load_issues(path: Path) -> list[dict]:
    """Load issue bundle JSON from a file path."""
    return json.loads(path.read_text(encoding="utf-8"))


def diff_issues(previous: list[dict], current: list[dict]) -> dict:
    """Compare previous and current issue bundles by root cause key."""
    current_by_key = {issue.get("root_cause_key", issue.get("title")): issue for issue in current}
    previous_by_key = {issue.get("root_cause_key", issue.get("title")): issue for issue in previous}
    statuses: list[dict] = []

    for key, old_issue in previous_by_key.items():
        new_issue = current_by_key.get(key)
        if new_issue is None:
            status = "FULLY_ADDRESSED"
        elif old_issue.get("severity") == new_issue.get("severity"):
            status = "NOT_ADDRESSED"
        else:
            status = "PARTIALLY_ADDRESSED"

        statuses.append(
            {
                "root_cause_key": key,
                "title": old_issue.get("title"),
                "previous_severity": old_issue.get("severity"),
                "current_severity": new_issue.get("severity") if new_issue else None,
                "status": status,
            }
        )

    new_items = [issue for key, issue in current_by_key.items() if key not in previous_by_key]
    return {"statuses": statuses, "new_issues": new_items}


def main() -> int:
    parser = argparse.ArgumentParser(description="Diff two deep-review issue bundle files")
    parser.add_argument("previous", help="Path to old final_issues.json")
    parser.add_argument("current", help="Path to new final_issues.json")
    args = parser.parse_args()

    diff = diff_issues(load_issues(Path(args.previous)), load_issues(Path(args.current)))
    print(json.dumps(diff, indent=2, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

